/* Standalone driver replicating the oss-fuzz "xml" target entry point.
 * Reads one input file and feeds it to LLVMFuzzerTestOneInput.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int LLVMFuzzerInitialize(int *argc, char ***argv);
int LLVMFuzzerTestOneInput(const char *data, size_t size);

int
main(int argc, char **argv) {
    FILE *f;
    char *buf;
    long len;
    int i;

    if (argc < 2) {
        fprintf(stderr, "usage: %s <input-file> [...]\n", argv[0]);
        return 1;
    }
    LLVMFuzzerInitialize(&argc, &argv);
    for (i = 1; i < argc; i++) {
        f = fopen(argv[i], "rb");
        if (f == NULL) {
            perror(argv[i]);
            return 1;
        }
        fseek(f, 0, SEEK_END);
        len = ftell(f);
        fseek(f, 0, SEEK_SET);
        buf = malloc(len > 0 ? (size_t) len : 1);
        if (buf == NULL) return 1;
        if (len > 0 && fread(buf, 1, (size_t) len, f) != (size_t) len) {
            perror("fread");
            return 1;
        }
        fclose(f);
        fprintf(stderr, "running on %s (%ld bytes)\n", argv[i], len);
        LLVMFuzzerTestOneInput(buf, (size_t) len);
        free(buf);
    }
    return 0;
}

